from django.db import migrations


def consolidate(apps, schema_editor):
    """整理历史数据：同一「人 + 项目 + 日期」只保留一条，并统一挂到最新提交的工卡。"""
    WorkHour = apps.get_model("formapp", "WorkHour")
    Submission = apps.get_model("formapp", "Submission")

    latest = {}
    for sid, name, project in Submission.objects.order_by("created_at", "id").values_list(
        "id", "name", "project"
    ):
        latest[(name, project)] = sid

    groups = {}
    for row in WorkHour.objects.order_by("id").values_list(
        "id", "name", "project", "date", "submission_id"
    ):
        groups.setdefault((row[1], row[2], row[3]), []).append(row)

    drop = []
    for key, rows in groups.items():
        if len(rows) == 1:
            continue
        # 优先保留最新工卡上的那条，其次保留最后写入的那条
        latest_id = latest.get((key[0], key[1]))
        preferred = [row for row in rows if row[4] == latest_id] or rows
        keep_id = preferred[-1][0]
        drop.extend(row[0] for row in rows if row[0] != keep_id)

    if drop:
        WorkHour.objects.filter(id__in=drop).delete()

    for name, project in {key[:2] for key in groups}:
        latest_id = latest.get((name, project))
        if latest_id:
            WorkHour.objects.filter(name=name, project=project).exclude(
                submission_id=latest_id
            ).update(submission_id=latest_id)


